import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { renderOpenApi } from "../../scripts/openapi.ts";

const REPO = join(import.meta.dirname, "../..");
const OPENAPI_PATH = join(REPO, "docs/openapi.yaml");

describe("openapi script", () => {
  it("matches committed docs/openapi.yaml", () => {
    const rendered = renderOpenApi();
    expect(rendered.startsWith(
      "# Generated by `npm run openapi`. Edit scripts/openapi-doc.ts (patches) and scripts/openapi-base.ts (operations), then rerun.\n",
    )).toBe(true);
    expect(readFileSync(OPENAPI_PATH, "utf8")).toEqual(rendered);
  });
});
